def today():
    return datetime.now(ZoneInfo('Europe/Zurich')).date()


def stamp():
    return datetime.now(ZoneInfo('Europe/Zurich')).isoformat(timespec='seconds')


def nice(value):
    return date.fromisoformat(value).strftime('%d.%m.%Y') if value else 'À préciser'


def normalize_prs(value):
    return re.sub(r'[\s-]', '', value).upper()


def valid_prs(value):
    return bool(re.fullmatch(r'PRS\d{3,20}', value))


PRS_FIELD_ID = '0fcbaa3f-fc7e-4d9d-a0d7-9d6496a7f5ac'
COST_FILE_FIELD_ID = '926eb7f5-f2ab-45e7-97c1-5ac5349345c8'
COST_FILE_BLOCK = 'Commande bloquée : le champ fichier coûts est vide dans le projet ClickUp. Faites renseigner ce champ avant de commander.'


def normalize_cost_link(value):
    """Normalize a URL value without following it or reading the document."""
    from urllib.parse import quote, urlsplit, urlunsplit
    if not isinstance(value,str):
        return ''
    value=value.strip()
    if not value or len(value)>16000 or any(ord(c)<32 or ord(c)==127 for c in value):
        return ''
    if value.startswith('//'):
        value='https:'+value
    elif not re.match(r'^[A-Za-z][A-Za-z0-9+.-]*:',value):
        # An omitted scheme is accepted only for an actual domain, not prose.
        if not re.match(r'^(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,63}(?::[0-9]+)?(?:[/?#]|$)',value):
            return ''
        value='https://'+value
    try:
        u=urlsplit(value)
        if u.scheme.lower() not in ('http','https') or not u.hostname or u.username or u.password:
            return ''
        if any(c.isspace() for c in u.netloc) or any(c in u.netloc for c in '<>"\\'):
            return ''
        if u.port is not None and not 0<u.port<65536:
            return ''
        host=u.hostname.encode('idna').decode('ascii')
        if not re.fullmatch(r'(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,63}',host):
            return ''
        # SharePoint filenames can contain unescaped spaces and accented letters.
        return urlunsplit((u.scheme.lower(),u.netloc,quote(u.path,safe="/%:@!$&'()*+,;=-._~"),
                          quote(u.query,safe="%=&/?+:;,@!$'()*-._~"),quote(u.fragment,safe="%/?+:;,@!$&'()*=-._~")))
    except (ValueError,UnicodeError):
        return ''


def cost_field_present(value):
    """Business rule: any non-empty value is sufficient, regardless of URL format."""
    if value is None:
        return False
    if isinstance(value,str):
        return bool(value.strip())
    if isinstance(value,(dict,list,tuple)):
        return bool(value)
    return True


def cost_file_check(task):
    fields=[f for f in task.get('custom_fields',[]) if isinstance(f,dict)]
    selected=next((f for f in fields if str(f.get('id'))==COST_FILE_FIELD_ID),None)
    value=selected.get('value') if selected else None
    link=normalize_cost_link(value)
    status='missing' if selected is None else 'valid' if cost_field_present(value) else 'empty'
    return {'status':status,'url':link,'task_id':str(task.get('id') or ''),
            'task_name':str(task.get('name') or ''),'field_id':COST_FILE_FIELD_ID,
            'field_name':str(selected.get('name') or '') if selected else '',
            'field_type':str(selected.get('type') or '') if selected else '',
            'value_type':type(value).__name__,
            'candidate_fields':[{'id':str(f.get('id') or ''),'name':str(f.get('name') or '')}
                for f in fields if 'fichier' in str(f.get('name','')).lower()
                and any(w in str(f.get('name','')).lower() for w in ('coût','cout'))][:10]}


def cost_file_link(task):
    return cost_file_check(task)['url']


class CostFileError(ValueError):
    def __init__(self,check):
        self.check={k:v for k,v in check.items() if k!='url'}
        reason={
            'missing':'ClickUp ne renvoie pas le champ fichier coûts attendu pour cette tâche. Vérifiez l’identifiant de la colonne et les droits du compte connecté.',
            'empty':'ClickUp renvoie ce champ vide pour cette tâche. Vérifiez le projet sélectionné et renseignez ce champ dans ClickUp.'
        }.get(check['status'],'Le contenu du champ fichier coûts ne peut pas être confirmé.')
        super().__init__('Commande bloquée : champ fichier coûts non renseigné. '+reason)


PROJECT_WORKSPACE_ID = '9015136987'
PROJECT_SPACE_IDS = ('90150382360', '90150756222')


def project_in_allowed_space(task):
    space=task.get('space')
    return isinstance(space,dict) and str(space.get('id','')) in PROJECT_SPACE_IDS


def project_matches(task, prs, field_id=PRS_FIELD_ID):
    # Le nom de la tâche ne constitue jamais une correspondance PRS.
    for field in task.get('custom_fields', []):
        if str(field.get('id')) != field_id:
            continue
        value=field.get('value')
        if isinstance(value,bool) or value is None:
            return False
        if isinstance(value,float) and value.is_integer():
            value=int(value)
        candidate=normalize_prs(str(value))
        if candidate.isdigit():
            candidate='PRS'+candidate
        return candidate==normalize_prs(prs)
    return False


def list_tasks(list_id, token):
    if not str(list_id).isdigit():
        raise ValueError('Identifiant de liste ClickUp invalide.')
    for page in range(200):
        response = api(f'list/{list_id}/task?' + urlencode({'page':page, 'include_closed':'true', 'include_timl':'true'}), token)
        tasks = response.get('tasks', [])
        yield from tasks
        if response.get('last_page') is True or not tasks:
            return
    raise ValueError('Cette liste est trop volumineuse. Limitez la recherche aux listes de projets pertinentes.')


def find_projects(prs, token=None):
    prs=normalize_prs(prs)
    if not valid_prs(prs):
        raise ValueError('Renseignez un PRS suivi de chiffres, par exemple PRS260184.')
    if not token:
        if demo_mode() and not configuration():
            return [{'id':'demo-'+prs,'name':DEMO_PROJECTS[prs],'source':'demo','cost_file_url':'https://example.com/fichier-couts'}] if prs in DEMO_PROJECTS else []
        raise AuthError('Cliquez sur « Synchroniser mon ClickUp » avant de rechercher un projet.')
    # Même en aperçu, une recherche réelle exige un compte autorisé.
    identity(token)
    if PROJECT_WORKSPACE_ID not in ids('CLICKUP_ALLOWED_WORKSPACE_IDS'):
        raise AuthError('L’espace Soleol doit être autorisé dans CLICKUP_ALLOWED_WORKSPACE_IDS.')
    results={}
    for page in range(200):
        query={'page':page,'include_closed':'true','subtasks':'false','space_ids[]':PROJECT_SPACE_IDS,
               'custom_fields':json.dumps([{'field_id':PRS_FIELD_ID,'operator':'=','value':prs[3:]}])}
        # Le filtre serveur contient les chiffres ; la vérification locale exige
        # ensuite le PRS complet exact, en tolérant espaces, tirets et préfixe PRS.
        response=api(f'team/{PROJECT_WORKSPACE_ID}/task?'+urlencode(query,doseq=True),token)
        tasks=response.get('tasks',[])
        for task in tasks:
            if project_in_allowed_space(task) and not task.get('parent') and not task.get('archived') and project_matches(task,prs):
                task_id=str(task.get('id') or '')
                name=str(task.get('name') or '').strip()
                if task_id and name:
                    results[task_id]={'id':task_id,'name':name,'source':'clickup','has_cost_file':cost_file_check(task)['status']=='valid'}
        if response.get('last_page') is True or not tasks:
            return list(results.values())
    raise ValueError('Trop de résultats ClickUp pour ce PRS. Vérifiez le numéro du projet.')


